model-based-testing.pseudocode:
def shortest_path(fsm, start, goal):
    queue, seen = [(start, [])], {start}
    while queue:  # BFS로 최단 이벤트열 탐색
        s, path = queue.pop(0)
        if s == goal:
            return path
        for event, nxt in fsm.get(s, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, path + [event]))
    return None

def gen_transition_tests(fsm, start):
    # fsm: {상태: [(이벤트, 다음 상태), ...]}
    tests = []
    for s in fsm:
        for event, nxt in fsm[s]:
            prefix = shortest_path(fsm, start, s)
            if prefix is not None:  # 도달 가능한 전이만
                # 전이 1개당 케이스 1개 (전이 커버리지)
                tests.append((prefix + [event], nxt))
    return tests

model-predictive-control.pseudocode:
def mpc_step(state, model, cost, constraints, horizon):
    # 예측 구간의 입력 시퀀스를 최적화
    def total_cost(u_seq):
        x = state
        c = 0.0
        for u in u_seq:
            x = model(x, u)  # 동역학 예측
            c += cost(x, u)
        return c
    u_seq = optimize(total_cost, constraints, horizon)
    return u_seq[0]  # 첫 입력만 적용 (Receding Horizon)

modulo-2-arithmetic.pseudocode:
def mod2_div(dividend, divisor):
    # 비트 리스트 모듈로-2 나눗셈 → 나머지 반환
    bits = [int(b) for b in dividend]
    g = [int(b) for b in divisor]
    n = len(g)
    for i in range(len(bits) - n + 1):
        if bits[i] == 1:  # 선두 비트 1일 때만 XOR
            for j in range(n):
                bits[i + j] ^= g[j]  # 빌림 없는 뺄셈
    return ''.join(map(str, bits[-(n - 1):]))

def crc_encode(data, gen):
    r = len(gen) - 1
    rem = mod2_div(data + '0' * r, gen)  # r비트 0 추가
    return data + rem  # 코드워드 = 데이터 + 나머지

def crc_check(codeword, gen):
    return set(mod2_div(codeword, gen)) == {'0'}

# crc_encode('1101', '1011') → '1101001'
# crc_check('1101001', '1011') → True

momentum.pseudocode:
def momentum_update(theta, grad, v, lr, beta=0.9):
    # v: 속도(과거 기울기의 지수이동평균)
    for j in range(len(theta)):
        v[j] = beta * v[j] + grad[j]  # 관성 누적
        theta[j] -= lr * v[j]  # 속도 방향으로 이동
    return theta, v

monitor-synchronization.pseudocode:
class BoundedBuffer:  # 모니터: 진입 상호배제는 런타임이 보장
    def __init__(self, n):
        self.buf, self.n = [], n
        self.not_full = Condition()  # 조건 변수
        self.not_empty = Condition()

    @synchronized  # 한 번에 한 스레드만 진입
    def put(self, item):
        while len(self.buf) == self.n:  # Mesa: while 재검사
            self.not_full.wait()  # 모니터 락 반납 후 대기
        self.buf.append(item)
        self.not_empty.signal()  # 대기 중 소비자 1개 깨움

    @synchronized
    def get(self):
        while not self.buf:
            self.not_empty.wait()
        item = self.buf.pop(0)
        self.not_full.signal()
        return item

monkey-testing.pseudocode:
def monkey_test(app, n_events, seed):
    rng = Random(seed)  # 시드 고정 → 같은 이벤트열 재현
    log = []
    for i in range(n_events):
        ev = rng.choice(['tap', 'swipe', 'key', 'back'])
        x, y = rng.randint(0, 1079), rng.randint(0, 1919)
        log.append((i, ev, x, y))
        try:
            app.inject(ev, x, y)
        except AppCrash:
            return 'crash', seed, log  # 시드·로그로 재현
    return 'pass', seed, log

monte-carlo-tree-search.pseudocode:
def mcts(root, budget, c=1.41):
    for _ in range(budget):
        node = root
        while node.children and not node.untried:
            node = best_ucb(node, c)  # 선택
        if node.untried:  # 확장
            node = node.expand()
        result = rollout(node.state)  # 무작위 시뮬레이션
        while node:  # 역전파
            node.visits += 1
            node.wins += result
            node = node.parent
    return max(root.children, key=lambda n: n.visits)

def best_ucb(node, c):
    import math
    def score(ch):
        exploit = ch.wins / ch.visits
        lnN = math.log(node.visits)
        explore = c * math.sqrt(lnN / ch.visits)
        return exploit + explore  # 탐험·활용 균형
    return max(node.children, key=score)
